Topics
- bas/<GATEWAY_ID>/status  retained  {"status":"online"} on connect, {"status":"offline"} as Last Will / on close
- bas/<GATEWAY_ID>/birth   retained  { gateway, timestamp, devices: [{ device_key, name, type, properties: [{ key, type, unit, acquisition, deadband, min, max, writable }] }] }
- bas/<GATEWAY_ID>/data    not retained  { timestamp, devices: { "<device_key>": { "<key>": value } } }

Both functions walk the snapshot the same way (SKIP_ROOT from the tab env), so data device keys match the birth.

func:
// ---------------------------------------------------------------------------
// BuildingBAS gateway birth
// In:   msg.payload = a data snapshot (nested JSON: site → system → device → points)
// Out 1 → MQTT node "connect": status birth (online) + Last Will (offline), both retained
// Out 2 → retained birth certificate on bas/<GATEWAY_ID>/birth, once connected
// Set GATEWAY_ID in this tab's environment variables (Flow properties → Environment).
// ---------------------------------------------------------------------------

const GATEWAY_ID = env.get("GATEWAY_ID");
if (!GATEWAY_ID) {
    node.error("Set GATEWAY_ID in this flow's environment variables");
    return null;
}

// Top-level keys that wrap the tree but aren't part of a device's identity.
// Shared with "Build data message" via the tab env, so device keys always match.
const SKIP_ROOT = (env.get("SKIP_ROOT") || "").split(",").map((s) => s.trim()).filter(Boolean);

// Point metadata. The first rule whose pattern matches the point key wins; anything a
// rule leaves out falls back to DEFAULTS, and "type" to the sample value's type.
// These are starting guesses: fill them in from the site's points list.
const RULES = [
    { match: /Temp$/,                    type: "float", unit: "°C", acquisition: "cov", deadband: 0.2, min: -40, max: 150 },
    { match: /SP$/,                      type: "float", unit: "°C", acquisition: "cov", writable: true },
    { match: /Amps$/,                    type: "float", unit: "A",  acquisition: "interval", min: 0 },
    { match: /(Output|Speed)$/,          type: "float", unit: "%",  acquisition: "interval", min: 0, max: 100 },
    { match: /OutputFreq$/,              type: "float", unit: "Hz", acquisition: "interval", min: 0 },
    { match: /(Command|Enable)$/,        type: "int",   acquisition: "cov", writable: true },
    { match: /(Status|State|Running|Alarm|Mode)$/, type: "int", acquisition: "cov" },
];
const DEFAULTS = { acquisition: "interval", writable: false };

// Device types. The first rule whose pattern matches the device key wins. A type must be a
// profile in the admin, written "key@major.minor". A device whose type is a known profile
// (and that reports its required properties) is accepted instantly as a new device; one
// with no type, or an unknown one, waits in the Birth certificates tab for review.
const TYPES = [
    { match: /\.DualTemp\.Zone\d+$/, type: "DualTemp-1@1.0" },
    // { match: /\.DHW\.Boiler\d+$/, type: "dhw-boiler@1.0" },
];

// --- parse input ------------------------------------------------------------
let snapshot = msg.payload;
if (Buffer.isBuffer(snapshot)) snapshot = snapshot.toString("utf8");
if (typeof snapshot === "string") {
    try { snapshot = JSON.parse(snapshot); }
    catch (e) { node.error("Snapshot is not valid JSON", msg); return null; }
}
if (!snapshot || typeof snapshot !== "object" || Array.isArray(snapshot)) {
    node.error("Snapshot must be a JSON object", msg);
    return null;
}

// --- find devices: any object holding plain values is a device ----------------
const isObject = (v) => v !== null && typeof v === "object" && !Array.isArray(v);
const devices = [];

function walk(obj, path) {
    const points = Object.entries(obj).filter(([, v]) => !isObject(v));
    if (points.length && path.length) devices.push({ path, points });
    for (const [k, v] of Object.entries(obj)) {
        if (isObject(v)) walk(v, [...path, k]);
    }
}

for (const [k, v] of Object.entries(snapshot)) {
    if (k === "timestamp" || !isObject(v)) continue;
    walk(v, SKIP_ROOT.includes(k) ? [] : [k]);
}

if (!devices.length) {
    node.error("No devices found in the snapshot", msg);
    return null;
}

// --- describe each point ----------------------------------------------------------
function inferType(value) {
    if (typeof value === "boolean") return "bool";
    if (typeof value === "number") return Number.isInteger(value) ? "int" : "float";
    return "string";
}

function describe(key, value) {
    const { match, ...meta } = RULES.find((r) => r.match.test(key)) || {};
    return { key, type: meta.type || inferType(value), ...DEFAULTS, ...meta };
}

const certificate = {
    gateway: GATEWAY_ID,
    timestamp: new Date().toISOString(),
    devices: devices.map(({ path, points }) => {
        const device_key = path.join(".");   // stable: e.g. Prudential301.DHW.Boiler1
        const type = (TYPES.find((t) => t.match.test(device_key)) || {}).type;
        return {
            device_key,
            name: path.slice(-2).join(" "),  // e.g. "DHW Boiler1"
            ...(type && { type }),
            properties: points.map(([key, value]) => describe(key, value)),
        };
    }),
};

// --- messages -----------------------------------------------------------------------
const statusTopic = `bas/${GATEWAY_ID}/status`;
const status = (s) => JSON.stringify({ status: s, gateway: GATEWAY_ID });

const connect = {
    action: "connect",
    broker: {
        clientid: `gateway-${GATEWAY_ID}`,
        birth: { topic: statusTopic, payload: status("online"),  qos: 1, retain: true },
        close: { topic: statusTopic, payload: status("offline"), qos: 1, retain: true },
        will:  { topic: statusTopic, payload: status("offline"), qos: 1, retain: true },
    },
};

const birth = {
    topic: `bas/${GATEWAY_ID}/birth`,
    payload: JSON.stringify(certificate),
    qos: 1,
    retain: true,
};

node.status({ fill: "green", shape: "dot", text: `${certificate.devices.length} devices` });
return [connect, birth];

// ---------------------------------------------------------------------------
// BuildingBAS gateway data
// In:   msg.payload = a data snapshot (nested JSON: site → system → device → points),
//       the same shape "Build status + birth" reads, so device keys match the birth.
// Out → bas/<GATEWAY_ID>/data (not retained):
//       { timestamp, devices: { "<device_key>": { "<key>": value, ... } } }
// Test aid: msg.simulate = true stamps "now" and nudges decimal values by up to ±2%.
// ---------------------------------------------------------------------------

const GATEWAY_ID = env.get("GATEWAY_ID");
if (!GATEWAY_ID) {
    node.error("Set GATEWAY_ID in this flow's environment variables");
    return null;
}
const SKIP_ROOT = (env.get("SKIP_ROOT") || "").split(",").map((s) => s.trim()).filter(Boolean);

let snapshot = msg.payload;
if (Buffer.isBuffer(snapshot)) snapshot = snapshot.toString("utf8");
if (typeof snapshot === "string") {
    try { snapshot = JSON.parse(snapshot); }
    catch (e) { node.error("Snapshot is not valid JSON", msg); return null; }
}
if (!snapshot || typeof snapshot !== "object" || Array.isArray(snapshot)) {
    node.error("Snapshot must be a JSON object", msg);
    return null;
}

const isObject = (v) => v !== null && typeof v === "object" && !Array.isArray(v);
const nudge = (v) => (msg.simulate && typeof v === "number" && !Number.isInteger(v))
    ? Math.round(v * (1 + (Math.random() - 0.5) * 0.04) * 10) / 10
    : v;

// Same walk as the birth: any object holding plain values is a device.
const devices = {};
function walk(obj, path) {
    const points = Object.entries(obj).filter(([, v]) => !isObject(v));
    if (points.length && path.length) {
        devices[path.join(".")] = Object.fromEntries(points.map(([k, v]) => [k, nudge(v)]));
    }
    for (const [k, v] of Object.entries(obj)) {
        if (isObject(v)) walk(v, [...path, k]);
    }
}
for (const [k, v] of Object.entries(snapshot)) {
    if (k === "timestamp" || !isObject(v)) continue;
    walk(v, SKIP_ROOT.includes(k) ? [] : [k]);
}

const count = Object.keys(devices).length;
if (!count) {
    node.error("No devices found in the snapshot", msg);
    return null;
}

const timestamp = !msg.simulate && snapshot.timestamp ? snapshot.timestamp : new Date().toISOString();
node.status({ fill: "green", shape: "dot", text: `${count} devices @ ${new Date().toLocaleTimeString()}` });

return {
    topic: `bas/${GATEWAY_ID}/data`,
    payload: JSON.stringify({ timestamp, devices }),
    qos: 1,
    retain: false,
};
